static RasterAsset pixelSprite(QString id,QString name,QStringList rows,QVector<quint16> palette){RasterAsset a;a.id=id;a.name=name;a.kind="sprite";a.width=a.height=16;a.palette=palette;a.pixels=QByteArray(256,0);for(int y=0;y<qMin(16,rows.size());++y)for(int x=0;x<qMin(16,rows[y].size());++x)a.pixels[y*16+x]=char(qMax(0,rows[y][x].digitValue()));return a;}
