 RasterAsset ts;ts.id="meadow_tiles";ts.name="Meadow tiles";ts.kind="tileset";ts.width=64;ts.height=8;ts.palette={green[0],green[1],toRgb555(QColor("#b0a068")),green[3]};ts.pixels=QByteArray(512,0);
 for(int y=0;y<8;++y)for(int x=0;x<64;++x){int t=x/8,px=x%8,c=0;if(t==0)c=(px==2&&y==5)?1:0;if(t==1)c=(px==0||y==0)?3:1;if(t==2)c=(px+y)%7==0?0:2;if(t==3)c=y<5&&(px>0&&px<7)?(y==0||y==4?3:2):(px==3||px==4?3:0);if(t==4)c=((px%3==0&&y>=2)||(y==6&&px%2))?3:1;if(t==5)c=(y==2||y==6)?0:3;if(t==6)c=y%3==0?3:2;if(t==7)c=px<2||px>5?2:3;ts.pixels[y*64+x]=c;}
 p.assets={ts,trainer,pikachu,bulb,charm,squirt};p.items={{"pokeball","Poke Ball","Throw from the battle Catch choice.","",20,false,"dialogue ball_help"},{"potion","Potion","Restores Pikachu to 20 HP.","",10,true,"set hp 20\ndialogue potion_used"},{"pikachu","Pikachu","Your electric starter.","pikachu",1,false,"dialogue dex_pikachu"},{"bulbasaur","Bulbasaur","A small grass Pokemon.","bulbasaur",1,false,"dialogue dex_bulbasaur"},{"charmander","Charmander","A small fire Pokemon.","charmander",1,false,"dialogue dex_charmander"},{"squirtle","Squirtle","A small water Pokemon.","squirtle",1,false,"dialogue dex_squirtle"}};
 p.storages={{"inventory","Bag",8,{{"pokeball",8},{"potion",3}}},{"party","Pokemon party",4,{{"pikachu",1}}}};
 auto script=[&](QString id,QString name,QString source){p.scripts<<GameScript{id,name,source};};
 script("show_battle","Show the wild Pokemon","if species == 1\n dialogue battle_bulbasaur\nelse\n if species == 2\n  dialogue battle_charmander\n else\n  dialogue battle_squirtle\n end\nend");
 script("wild_encounter","Start a wild encounter","if hp > 0\n set wild_hp 10\n random species 1 3\n call show_battle\nend");
 script("hurt_player","Wild Pokemon attacks","random damage 1 3\nsub hp damage\nif hp < 0\n set hp 0\nend");
 script("attack_turn","Pikachu attacks","random damage 2 4\nsub wild_hp damage\nif wild_hp <= 0\n set wild_hp 0\n add wins 1\n dialogue victory\nelse\n call hurt_player\n if hp == 0\n  dialogue fainted\n else\n  call show_battle\n end\nend");
 QString capture;QStringList species{"bulbasaur","charmander","squirtle"};for(int i=0;i<3;++i){if(i<2)capture+=QString("if species == %1\n").arg(i+1);capture+=QString("if has party %1 >= 1\n dialogue already_owned\nelse\n give party %1 1\n if result == 1\n  add caught 1\n  dialogue caught_%1\n else\n  dialogue party_full\n end\nend\n").arg(species[i]);if(i<2)capture+="else\n";}capture+="end\nend\n";script("store_capture","Store a caught Pokemon",capture);
 script("throw_ball","Try to catch the wild Pokemon","take inventory pokeball 1\nif result == 1\n random roll 1 100\n if wild_hp <= 4\n  set roll 1\n end\n if roll <= 35\n  call store_capture\n else\n  call hurt_player\n  if hp == 0\n   dialogue fainted\n  else\n   dialogue catch_failed\n  end\n end\nelse\n dialogue no_balls\nend");
 script("heal","Heal and refill balls","set hp 20\nif has inventory pokeball < 5\n give inventory pokeball 5\nend");
 script("report","Check the collection","if has party bulbasaur >= 1\n if has party charmander >= 1\n  if has party squirtle >= 1\n   dialogue complete\n  else\n   dialogue progress\n  end\n else\n  dialogue progress\n end\nelse\n dialogue progress\nend");
 auto prompt=[&](QString id,QString title,QString text,QVector<Choice> choices,QString enter="",QString portrait="",bool modal=false){Prompt n;n.id=id;n.title=title;n.text=text;n.choices=choices;n.onEnter=enter;n.portrait=portrait;n.modal=modal;n.textbox={0,5,20,13};int index=p.prompts.size();n.position={double(index%4*330),double(index/4*280)};p.prompts<<n;};
 auto leave=QVector<Choice>{{"Back to trail","intro","","resume"}};
 prompt("intro","POCKET MEADOW","Pikachu is yours!\nCatch 3 wild Pokemon\nin the long grass.\nNurse heals north.",leave,"","pikachu");
 for(auto id:species){QString name=id;name[0]=name[0].toUpper();prompt("battle_"+id,"WILD "+name.toUpper(),"Wild HP {wild_hp}\nPikachu HP {hp}\nWeaken, then catch!",{{"Fight","resolve_fight"},{"Catch","resolve_catch","has inventory pokeball >= 1",""},{"Run","escaped"}},"",id,true);prompt("caught_"+id,"CAUGHT "+name.toUpper(),name+" joins\nyour party!\nCaught {caught} of 3",leave,"",id,true);prompt("dex_"+id,name.toUpper(),"A wild friend from\nthe meadow.\nUse the PC to view\nyour collection.",leave,"",id);}
 prompt("resolve_fight","BATTLE","Pikachu attacks!",{},"call attack_turn","pikachu",true);
 prompt("resolve_catch","POKE BALL","Throwing a ball...",{},"call throw_ball","pikachu",true);
 prompt("battle_router","BATTLE","A wild Pokemon!",{},"call show_battle","pikachu",true);
 prompt("victory","VICTORY","The wild Pokemon\nfled after battle.\nWins {wins}\nTry catching next!",leave,"","pikachu",true);
 prompt("escaped","GOT AWAY","You escaped safely.",leave,"","pikachu",true);
