 prompt("potion_used","POTION USED","Pikachu HP {hp}\nReady to explore!",leave,"","pikachu");prompt("ball_help","POKE BALLS","Use Catch during\nbattle. Weaken wild\nPokemon to 4 HP\nfor a sure catch.",leave);
